import{_ as i,C as n,o as l,c as r,a5 as t,E as s}from"./chunks/framework.OnpWQ13d.js";const m=JSON.parse('{"title":"Salsa Incremental Query Engine","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/salsa-queries.md","filePath":"architecture/salsa-queries.md","lastUpdated":1790751392000}'),o={name:"architecture/salsa-queries.md"};function d(c,e,u,h,p,y){const a=n("MermaidBlock");return l(),r("div",null,[e[0]||(e[0]=t('<h1 id="salsa-incremental-query-engine" tabindex="-1">Salsa Incremental Query Engine <a class="header-anchor" href="#salsa-incremental-query-engine" aria-label="Permalink to &quot;Salsa Incremental Query Engine&quot;">​</a></h1><p>ModelScript&#39;s semantic analysis and symbol resolution pipeline is driven by an incremental query computation engine inspired by the open-source <a href="https://github.com/salsa-rs/salsa" target="_blank" rel="noreferrer">Salsa</a> incremental query framework.</p><p>The engine lives in <code>@modelscript/runtime</code> and provides memoized, demand-driven evaluation across multi-file engineering workspaces.</p><hr><h2 id="the-query-life-cycle" tabindex="-1">The Query Life Cycle <a class="header-anchor" href="#the-query-life-cycle" aria-label="Permalink to &quot;The Query Life Cycle&quot;">​</a></h2><p>Every query executed in ModelScript follows a 4-phase lifecycle to ensure maximum cache re-use and correct invalidation:</p>',6)),s(a,{code:"sequenceDiagram%0A%20%20%20%20participant%20Caller%0A%20%20%20%20participant%20Salsa%20as%20QueryEngine%0A%20%20%20%20participant%20Storage%20as%20DependencyGraph%0A%0A%20%20%20%20Caller-%3E%3ESalsa%3A%20query(key)%0A%20%20%20%20alt%20Cache%20hit%20%26%20revision%20current%0A%20%20%20%20%20%20%20%20Salsa--%3E%3ECaller%3A%20Cached%20result%20(immediate)%0A%20%20%20%20else%20Revision%20changed%0A%20%20%20%20%20%20%20%20Salsa-%3E%3EStorage%3A%20deep_verify(dependencies)%0A%20%20%20%20%20%20%20%20alt%20All%20dependencies%20unchanged%0A%20%20%20%20%20%20%20%20%20%20%20%20Storage--%3E%3ESalsa%3A%20verified%20valid%0A%20%20%20%20%20%20%20%20%20%20%20%20Salsa-%3E%3ESalsa%3A%20backdate%20revision%0A%20%20%20%20%20%20%20%20%20%20%20%20Salsa--%3E%3ECaller%3A%20Cached%20result%0A%20%20%20%20%20%20%20%20else%20Any%20dependency%20changed%0A%20%20%20%20%20%20%20%20%20%20%20%20Storage--%3E%3ESalsa%3A%20invalid%0A%20%20%20%20%20%20%20%20%20%20%20%20Salsa-%3E%3ESalsa%3A%20execute%20query%20function%0A%20%20%20%20%20%20%20%20%20%20%20%20Salsa-%3E%3EStorage%3A%20record%20new%20dependencies%0A%20%20%20%20%20%20%20%20%20%20%20%20Salsa--%3E%3ECaller%3A%20Fresh%20computed%20result%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A"}),e[1]||(e[1]=t('<h3 id="the-4-stages" tabindex="-1">The 4 Stages <a class="header-anchor" href="#the-4-stages" aria-label="Permalink to &quot;The 4 Stages&quot;">​</a></h3><ol><li><strong><code>fetch</code></strong>: Checks if the query result exists in the memoization table.</li><li><strong><code>deep_verify</code></strong>: If the workspace revision has advanced, transitively checks whether any input queries or files that contributed to this result have actually changed.</li><li><strong><code>execute</code></strong>: Re-runs the query definition if inputs have genuinely changed, tracking any newly accessed queries.</li><li><strong><code>backdate</code></strong>: If re-executing the query produces an output value identical to the previous result, the query&#39;s revision is backdated to prevent cascading invalidation down the dependency tree.</li></ol><hr><h2 id="key-compiler-queries" tabindex="-1">Key Compiler Queries <a class="header-anchor" href="#key-compiler-queries" aria-label="Permalink to &quot;Key Compiler Queries&quot;">​</a></h2><p>The query engine handles semantic resolution, type checking, and specialization:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Query</th><th style="text-align:left;">Scope</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>instantiate</code></td><td style="text-align:left;">Class</td><td style="text-align:left;">Resolves all direct components, inherited elements, and nested declarations of a class.</td></tr><tr><td style="text-align:left;"><code>classInstance</code></td><td style="text-align:left;">Component</td><td style="text-align:left;">Specializes a generic class definition with specific modifier expressions.</td></tr><tr><td style="text-align:left;"><code>resolveSimpleName</code></td><td style="text-align:left;">Scope</td><td style="text-align:left;">Performs hierarchical lexical scoping and imports resolution.</td></tr><tr><td style="text-align:left;"><code>variability</code></td><td style="text-align:left;">Component</td><td style="text-align:left;">Computes effective variability: <code>constant</code>, <code>parameter</code>, <code>discrete</code>, or <code>continuous</code>.</td></tr><tr><td style="text-align:left;"><code>causality</code></td><td style="text-align:left;">Component</td><td style="text-align:left;">Computes signal causality: <code>input</code>, <code>output</code>, or <code>internal</code>.</td></tr><tr><td style="text-align:left;"><code>effectiveModification</code></td><td style="text-align:left;">Hierarchy</td><td style="text-align:left;">Resolves and merges class modification clauses across multi-level inheritance graphs.</td></tr></tbody></table><hr><h2 id="salsa-linear-cst-synergy" tabindex="-1">Salsa &amp; Linear CST Synergy <a class="header-anchor" href="#salsa-linear-cst-synergy" aria-label="Permalink to &quot;Salsa &amp; Linear CST Synergy&quot;">​</a></h2><p>AST wrapper nodes are <strong>never</strong> stored inside the Salsa cache. Storing heavy AST objects would duplicate memory and defeat garbage collection guarantees.</p><p>Instead:</p><ul><li>The Salsa cache stores semantic integer handles and primitive metadata (e.g. <code>SymbolId</code>, resolved <code>TypeInfo</code>, variability enums).</li><li>Concrete CST nodes are retrieved on-demand from linear memory using <code>db.cstNode(symbolId)</code> only when lowering or evaluating equations.</li></ul>',11))])}const f=i(o,[["render",d]]);export{m as __pageData,f as default};
